h=h.replace('<label for="alignmentMode">不重合区域是否对齐</label>', '<label for="overlapAlignment">重合区域是否对齐</label><select id="overlapAlignment" aria-label="重合区域是否对齐"><option value="yes">是（保留对应连接）</option><option value="no">否（按本层优化最少点）</option></select><label for="alignmentMode">不重合区域是否对齐</label>')
